SELECT N.ID, N.NOME, N.ESTADO, (SELECT MAX(L.TRECHO) FROM LIVROS_INDICADOS L WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME) TRECHO, (SELECT MAX(NULLIF(L.AUTOR, '')) FROM LIVROS_INDICADOS L WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME) AUTOR FROM LIVROS_NOMES N WHERE N.ESTADO IN ('MUSICA', 'AUDIOVISUAL', 'SAGRADO') AND N.CONFERIDO IS NULL ORDER BY N.ID LIMIT {{limit}}